function key(code,down){try{if(localGBData&&frame.src.indexOf('/gb/')>=0){frame.contentWindow.postMessage({type:'olddays-gb-key',code:code,down:down},location.origin);return;}if(code===-6||code===-7){var button=code===-6?frame.contentDocument.getElementById('header-drawer-button'):frame.contentDocument.querySelector('#header-ok-button button');if(button&&button.getClientRects().length){if(down)button.click();return;}}code=({"-1":119,"-2":115,"-3":97,"-4":100,"-5":32})[code]||code;var m=frame.contentWindow.MIDP;if(m)(down?m.sendKeyPress:m.sendKeyRelease)(code);}catch(_){}}

document.querySelectorAll('[data-key]').forEach(function(b){b.addEventListener('pointerdown',function(e){e.preventDefault();b.setPointerCapture(e.pointerId);setJavaKey(Number(b.dataset.key),true);});b.addEventListener('pointerup',function(){setJavaKey(Number(b.dataset.key),false);});b.addEventListener('pointercancel',function(){setJavaKey(Number(b.dataset.key),false);});});
var map={ArrowUp:-1,ArrowDown:-2,ArrowLeft:-3,ArrowRight:-4,Enter:-5,F1:-6,F2:-7};
['keydown','keyup'].forEach(function(type){window.addEventListener(type,function(e){if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;var c=map[e.key];if(c===undefined&&/^[0-9*#]$/.test(e.key))c=e.key.charCodeAt(0);if(c!==undefined){e.preventDefault();setJavaKey(c,type==='keydown');}});});
async function importLocalJar(file){var ticket=++javaLoadTicket;if(file.size>8*1024*1024){message.textContent='请导入 8 MB 以内的 JAR。';publishGameStatus(message.textContent,false);return;}try{var data=await file.arrayBuffer();if(ticket!==javaLoadTicket)return;var zip=new ZipFile(data);var entry=zip.directory&&Object.keys(zip.directory).find(function(n){return n.toUpperCase()==='META-INF/MANIFEST.MF';});if(Object.keys(zip.directory||{}).length>5000||Object.values(zip.directory||{}).reduce(function(n,x){return n+(x.uncompressed_len||0);},0)>64*1024*1024)throw Error("large archive");if(entry&&zip.directory[entry].uncompressed_len>65536)throw Error("large manifest");var bytes=entry&&zip.read(entry);if(!bytes||bytes.length>65536)throw Error('manifest');var text=new TextDecoder().decode(bytes).replace(/\r\n?/g,'\n').replace(/\n /g,'');var line=text.split('\n').find(function(x){return /^MIDlet-1:\s*/i.test(x);});var cls=line&&line.split(',').pop().trim();if(!cls||!/^[\w.$]+$/.test(cls))throw Error('class');silentAudioPipes.clear();releaseJavaKeys();gameReady=false;localJarData=data;localJarManifest=text;localJarStorage=jarStorageKey(data);localJarClass=cls;localJarName=file.name;localGBData=extractMeBoyRom(zip,cls);if(localGBData){localJarStorage="gb-"+jarStorageKey(localGBData.buffer);message.textContent='MeBoy 游戏 · GBC兼容模式 · 5=A / 0=B / #=开始 / 1存档 / 3读档';frame.src='gb/index.html?v=0.8.5';publishGameStatus('正在以GBC兼容模式载入MeBoy游戏…',false);return;}frame.src='main.html?jars=local.jar&jad=&storageKey='+localJarStorage+'&midletClassName='+encodeURIComponent(cls)+'&autosize=1&fontSize=12';message.textContent='本机运行：'+file.name+' · 不上传';publishGameStatus('正在导入 '+file.name+' · 仅本机运行',false);}catch(_){message.textContent='无法读取 MIDlet-1 清单，请选择有效的 Java ME JAR。';publishGameStatus(message.textContent,false);}}
