var requested=new URLSearchParams(location.search).get('demo'),requestedUnsupported=Boolean(requested&&!Array.from(document.getElementById('demo').options).some(function(o){return o.value===requested;}));if(requested&&!requestedUnsupported)document.getElementById('demo').value=requested;
