function jarStorageKey(buffer){var bytes=new Uint8Array(buffer),a=2166136261,b=5381;for(var i=0;i<bytes.length;i++){a=Math.imul(a^bytes[i],16777619);b=(Math.imul(b,33)^bytes[i])>>>0;}return "jar-"+(a>>>0).toString(16)+"-"+b.toString(16)+"-"+bytes.length;}

function extractMeBoyRom(zip,cls){if(cls!=='MeBoy')return null;var keys=Object.keys(zip.directory),first=keys.find(n=>/BYTE0$/.test(n));if(!first)return null;var base=first.slice(0,-1),parts=[],size=0;for(var i=0;i<64;i++){if(!zip.directory[base+i])break;var part=zip.read(base+i);size+=part.length;if(size>8*1024*1024)throw Error('ROM too large');parts.push(part);}if(size<32768)return null;var data=new Uint8Array(size),offset=0;parts.forEach(p=>{data.set(p,offset);offset+=p.length;});return data;}

